import sys

s = sys.stdin.read()
out = []
i = 0
n = len(s)

while i < n:
    if s[i] == ' ':
        j = i
        while j < n and s[j] == ' ':
            j += 1
        count = j - i
        if count >= 3:
            out.append('-')
        else:
            out.extend(['_'] * count)
        i = j
    else:
        out.append('_')
        i += 1

sys.stdout.write(''.join(out))

