import sys

NUMS = ["zero","one","two","three","four","five","six","seven","eight","nine"]
ORDER = {w: i for i, w in enumerate(NUMS)}

data = sys.stdin.read().strip()
if not data:
    print("")
else:
    words = data.split()
    words.sort(key=lambda w: ORDER[w])
    print(" ".join(words))
